try {
  const url = $input.item.json.youtube_url;
  const match = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([^&\n?#]+)/);
  if (!match) throw new Error('URL YouTube tidak valid: ' + url);
  return [{ json: {
    youtube_url: url,
    video_id: match[1],
    gdrive_folder_id: $input.item.json.gdrive_folder_id
  }}];
} catch (error) {
  return [{ json: { error: error.message, success: false } }];
}

try {
  const data = $input.item.json;
  const videoMeta = $('Extract Video ID').item.json;
  const oEmbed = $('Get Video Meta').item.json;

  if (!data.content || data.content.length === 0) {
    throw new Error('Transcript kosong dari Supadata. Cek API key dan pastikan video punya caption.');
  }

  const transcriptText = data.content
    .map(seg => (seg.text || '').replace(/\n/g, ' ').trim())
    .filter(t => t.length > 0)
    .join('\n');

  const today = new Date().toISOString().split('T')[0];
  const videoId = videoMeta.video_id;
  const youtubeUrl = videoMeta.youtube_url;
  const lang = data.lang || 'id';
  const title = oEmbed.title || videoId;
  const author = oEmbed.author_name || 'Unknown';

  const cleanTitle = title.replace(/[^a-zA-Z0-9\s\-_]/g, '').trim().replace(/\s+/g, '_').substring(0, 60);
  const filename = 'Transcript_' + cleanTitle + '_' + today + '.md';

  const markdown = [
    '# Transcript: ' + title,
    '',
    '**Channel / Author:** ' + author,
    '**Video ID:** ' + videoId,
    '**URL:** ' + youtubeUrl,
    '**Bahasa:** ' + lang,
    '**Tanggal Transcript:** ' + today,
    '**Total Segments:** ' + data.content.length,
    '',
    '---',
    '',
    transcriptText,
  ].join('\n');

  return [{ json: {
    video_id:        videoId,
    title,
    author,
    youtube_url:     youtubeUrl,
    language:        lang,
    transcript_text: transcriptText,
    markdown,
    filename,
    line_count:      data.content.length,
    gdrive_folder_id: videoMeta.gdrive_folder_id || '',
  }}];
} catch (error) {
  return [{ json: { error: error.message, success: false } }];
}
